import React, { useState, useEffect } from "react";
import DoctorSidebar from "../../component/DoctorSidebar";
import axios from "axios";

const DoctorProfile = () => {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    doctorId: "",
    specialty: "",
    password: "",
    confirmPassword: "",
  });

  const [message, setMessage] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [isLoadingProfile, setIsLoadingProfile] = useState(true);

  useEffect(() => {
    const fetchProfile = async () => {
      try {
        const token = JSON.parse(localStorage.getItem("token"));
        const response = await axios.get(
          "https://us-central1-e-health-7d458.cloudfunctions.net/api/doctors/profile",
          {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          }
        );

        const { doctor } = response.data;
        setFormData((prev) => ({
          ...prev,
          name: doctor.doctorName,
          email: doctor.email,
          doctorId: doctor.doctorId,
          specialty: doctor.specialty,
        }));
      } catch (error) {
        setMessage(error.response?.data?.message || "Error loading profile");
      } finally {
        setIsLoadingProfile(false);
      }
    };

    fetchProfile();
  }, []);

  const handleChange = (e) => {
    setFormData((prev) => ({
      ...prev,
      [e.target.name]: e.target.value,
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setMessage("");

    if (formData.password && formData.password !== formData.confirmPassword) {
      setMessage("Passwords do not match.");
      setIsLoading(false);
      return;
    }

    try {
      const token = JSON.parse(localStorage.getItem("token"));
      const response = await axios.put(
        "https://us-central1-e-health-7d458.cloudfunctions.net/api/doctors/profileupdate",
        {
          name: formData.name,
          email: formData.email,
          password: formData.password || undefined,
        },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      setMessage("Profile updated successfully!");
      // Update local state with new data
      setFormData((prev) => ({
        ...prev,
        name: response.data.doctor.doctorName,
        email: response.data.doctor.email,
        password: "",
        confirmPassword: "",
      }));
    } catch (error) {
      setMessage(error.response?.data?.message || "Error updating profile");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <DoctorSidebar>
      <div className="mx-auto w-full">
        <h1 className="text-2xl font-bold mb-6 text-[#F26522]">Edit Profile</h1>

        {isLoadingProfile ? (
          <div className="text-center py-4">
            <p className="text-gray-600">Loading profile...</p>
          </div>
        ) : (
          <form
            onSubmit={handleSubmit}
            className="bg-white rounded-xl shadow-md p-6 space-y-6"
          >
            {message && (
              <p
                className={`text-sm text-center font-medium ${message.includes("success")
                    ? "text-green-600"
                    : "text-red-600"
                  }`}
              >
                {message}
              </p>
            )}

            {/* Basic Info */}
            <div>
              <h2 className="text-lg font-semibold text-gray-700 mb-4">
                Basic Information
              </h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm text-gray-500 mb-1">
                    Full Name
                  </label>
                  <input
                    type="text"
                    name="name"
                    value={formData.name}
                    onChange={handleChange}
                    className="w-full bg-gray-50 px-4 py-2 rounded-md focus:ring-2 focus:ring-[#F26522] outline-none border"
                  />
                </div>

                <div>
                  <label className="block text-sm text-gray-500 mb-1">
                    Email
                  </label>
                  <input
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleChange}
                    className="w-full bg-gray-50 px-4 py-2 rounded-md focus:ring-2 focus:ring-[#F26522] outline-none border"
                  />
                </div>
              </div>
            </div>

            {/* Identification */}
            <div>
              <h2 className="text-lg font-semibold text-gray-700 mb-4">
                Identification
              </h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm text-gray-500 mb-1">
                    Doctor ID
                  </label>
                  <input
                    type="text"
                    value={formData.doctorId}
                    disabled
                    className="w-full bg-gray-100 text-gray-500 px-4 py-2 rounded-md border cursor-not-allowed"
                  />
                </div>

                <div>
                  <label className="block text-sm text-gray-500 mb-1">
                    Specialty
                  </label>
                  <input
                    type="text"
                    value={formData.specialty}
                    disabled
                    className="w-full bg-gray-100 text-gray-500 px-4 py-2 rounded-md border cursor-not-allowed"
                  />
                </div>
              </div>
            </div>

            {/* Password Update */}
            <div>
              <h2 className="text-lg font-semibold text-gray-700 mb-4">
                Change Password{" "}
                <span className="text-sm text-gray-400">(optional)</span>
              </h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm text-gray-500 mb-1">
                    New Password
                  </label>
                  <input
                    type="password"
                    name="password"
                    value={formData.password}
                    onChange={handleChange}
                    placeholder="Leave blank to keep current"
                    className="w-full bg-gray-50 px-4 py-2 rounded-md focus:ring-2 focus:ring-[#F26522] outline-none border"
                  />
                </div>

                <div>
                  <label className="block text-sm text-gray-500 mb-1">
                    Confirm Password
                  </label>
                  <input
                    type="password"
                    name="confirmPassword"
                    value={formData.confirmPassword}
                    onChange={handleChange}
                    className="w-full bg-gray-50 px-4 py-2 rounded-md focus:ring-2 focus:ring-[#F26522] outline-none border"
                  />
                </div>
              </div>
            </div>

            <div className="pt-2">
              <button
                type="submit"
                disabled={isLoading}
                className={`bg-[#F26522] w-full text-white py-2 rounded-md hover:bg-orange-600 transition ${isLoading ? "opacity-50 cursor-not-allowed" : ""
                  }`}
              >
                {isLoading ? "Saving..." : "Save Changes"}
              </button>
            </div>
          </form>
        )}
      </div>
    </DoctorSidebar>
  );
};

export default DoctorProfile;
